SELECT COUNT(*) AS "count_result" FROM triples t0, triples t1 WHERE t0.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/likes' AND struct_pack(kind := 0::UTINYINT, value := t1.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) = struct_pack(kind := 0::UTINYINT, value := t0.s, datatype := NULL::VARCHAR, lang := NULL::VARCHAR) AND t1.p = 'http://db.uwaterloo.ca/~galuc/wsdbm/subscribes' AND t1.o = struct_pack(kind := 0::UTINYINT, value := 'http://db.uwaterloo.ca/~galuc/wsdbm/Website2855', datatype := NULL::VARCHAR, lang := NULL::VARCHAR)